'use client';
import * as React from 'react';
import { useState, useEffect } from 'react';
import { Button, Card, Form, Input, message, Alert, Select, SelectProps } from 'antd';
import { Prompt } from '@/contexts/SettingsContext';
import '@ant-design/v5-patch-for-react-19';
import Link from 'next/link';
import { useSettings } from '@/contexts/SettingsContext';
import { SettingOutlined } from '@ant-design/icons';
import dynamic from 'next/dynamic';
import axios from 'axios';

const MindMap = dynamic(() => import('@/components/MindMap'), { ssr: false });
const { TextArea } = Input;

import { HierarchyNode, HierarchyData } from '@/types/hierarchy';

/**
 * Parse content into a hierarchical structure
 * @param content The content to parse
 * @returns The parsed content as a JSON string
 */
function parseContent(content: string): string {
  const lines = content.split(/\r?\n/);
  const sections: HierarchyNode[] = [];
  let currentSection: HierarchyNode | null = null;

  lines.forEach((line) => {
    const headerMatch = line.match(/^#\s*\*\*(.+?)\*\*/);
    if (headerMatch) {
      const sectionText = headerMatch[1].trim();
      currentSection = { 
        id: `section-${sections.length + 1}`,
        text: sectionText,
        children: [] 
      };
      sections.push(currentSection);
    } else if (/^[-*]\s+/.test(line) && currentSection) {
      const itemText = line.replace(/^[-*]\s+/, '').trim();

      currentSection.children!.push({
        id: `item-${currentSection.children!.length + 1}`,
        text: itemText,
        children: []
      });
    }
  });

  const tree = { 
    root: { 
      id: 'root', 
      text: 'Test Cases', 
      children: sections 
    } 
  };
  return JSON.stringify(tree, null, 2);
}

export default function Home(): React.ReactNode {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState<boolean>(false);
  const [apiConfigured, setApiConfigured] = useState<boolean>(true);
  const [showMindMap, setShowMindMap] = useState<boolean>(false);
  const [mindMapData, setMindMapData] = useState<HierarchyData | null>(null);
  const [prdContent, setPrdContent] = useState<string>('');
  const { apiKey, apiUrl, model, selectedPromptId, prompts = [], setSelectedPrompt } = useSettings();

  useEffect(() => {
    setApiConfigured(!!apiKey);
  }, [apiKey]);

  const onFinish = async (values: { prd: string }): Promise<void> => {
    try {
      setLoading(true);
      const selectedPrompt = selectedPromptId
        ? prompts.find((p: Prompt) => p.id === selectedPromptId)
        : prompts.find((p: Prompt) => p.isDefault) || prompts[0];

      if (!selectedPrompt) {
        message.error('No prompt available. Please create a prompt in settings.');
        return;
      }
      if (!apiKey) {
        message.error('API key is required');
        return;
      }

      const prompt = `${selectedPrompt.content}\n\nPRD: ${values.prd}`;
      const response = await axios.post(
        apiUrl || 'https://ark.cn-beijing.volces.com/api/v3/chat/completions',
        {
          model: model || 'doubao-1.5-pro-256k-250115',
          messages: [
            { role: 'system', content: 'You are a helpful assistant that generates test cases in a structured mind map format.' },
            { role: 'user', content: prompt }
          ],
          temperature: 0.7,
        },
        {
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${apiKey}`
          }
        }
      );

      const content = response.data.choices?.[0]?.message?.content;
      if (!content) throw new Error('No content in response');

      const contentJson = parseContent(content);
      const data = JSON.parse(contentJson) as HierarchyData;
      console.log(data);


      setPrdContent(values.prd);
      setMindMapData(data);
      setShowMindMap(true);
      document.getElementById('mind-map-container')?.scrollIntoView({ behavior: 'smooth' });
    } catch (error) {
      console.error('Error generating test cases:', error);
      message.error('Failed to generate test cases. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (showMindMap && mindMapData) {
    return (
      <div className="min-h-screen bg-gray-50 p-4 md:p-8">
        <div className="max-w-6xl mx-auto">
          <Button onClick={() => setShowMindMap(false)} className="mb-4">← Back to Form</Button>
          <div id="mind-map-container" className="bg-white rounded-lg shadow-md p-4">
            <MindMap data={mindMapData} prdContent={prdContent} />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 md:p-8">
      <div className="max-w-4xl mx-auto">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold">PRD Test Case Generator</h1>
          <div className="flex items-center gap-4">
            <Select
              value={selectedPromptId}
              onChange={(val) => setSelectedPrompt(val as string)}
              placeholder="Select a prompt"
              style={{ width: 200 }}
              options={prompts.map((prompt: Prompt) => ({ label: prompt.name, value: prompt.id })) as SelectProps['options']}
            />
            <Link href="/settings"><Button icon={<SettingOutlined />}>Settings</Button></Link>
          </div>
        </div>

        {!apiConfigured && (
          <Alert
            message="Warning"
            description="API key is not configured. Please configure your API settings to generate test cases."
            type="warning"
            showIcon
            className="mb-6"
            action={<Link href="/settings"><Button size="small" type="primary">Go to Settings</Button></Link>}
          />
        )}

        <Card>
          <Form<{ prd: string }> form={form} layout="vertical" onFinish={onFinish} initialValues={{ prd: '' }}>
            <Form.Item name="prd" label="PRD Description" rules={[{ required: true, message: 'Please input PRD description!' }]}>  
              <TextArea rows={12} placeholder="Enter your Product Requirements Document (PRD) here..." className="w-full" />
            </Form.Item>
            <Form.Item>
              <Button type="primary" htmlType="submit" loading={loading} size="large" className="w-full sm:w-auto">
                Generate Test Cases
              </Button>
            </Form.Item>
          </Form>
        </Card>

        <div className="mt-8 text-center text-sm text-gray-500">
          <p>Enter your PRD and click &quot;Generate Test Cases&quot; to create a mind map of test cases.</p>
        </div>
      </div>
    </div>
  );
}
